package cn.lvxu.travel;
import android.widget.*;import java.time.*;import java.util.*;
final class OnThisDayUi {
 private final MainActivity a;OnThisDayUi(MainActivity a){this.a=a;}
 void show(){PageUi page=new PageUi(a,"那年今日");List<MemoriesQuery.Memory> memories=MemoriesQuery.forDate(a.trips,LocalDate.now());if(memories.isEmpty())page.body.addView(a.text("今天还没有往年的旅行记忆。去记录下一次出发吧。",14,MainActivity.MUTED));int year=-1;for(MemoriesQuery.Memory m:memories){if(year!=m.year){year=m.year;page.body.addView(a.bold(year+" 年",20,MainActivity.INK));}LinearLayout c=a.card(page.body);c.addView(a.bold(m.kind+" · "+m.title,18,MainActivity.INK));c.addView(a.text(m.date+" · "+m.detail,14,MainActivity.MUTED));if(!m.photo.isEmpty())try{java.io.File photo=MediaFiles.file(a,m.photo);if(photo.isFile()){ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(photo.getPath(),options);options.inSampleSize=Math.max(1,Math.max(options.outWidth,options.outHeight)/800);options.inJustDecodeBounds=false;image.setImageBitmap(android.graphics.BitmapFactory.decodeFile(photo.getPath(),options));c.addView(image,new LinearLayout.LayoutParams(-1,a.dp(180)));}}catch(Exception ignored){}c.addView(a.action("查看这段回忆",false,()->a.openSearchResult(new SearchIndex.Result(m.kind,m.tripId,m.itemId,m.title,m.detail,0))));}page.show();}
}
